<?php require '../config.php';header('Content-Type: application/json');requireLogin();$uid=(int)$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='GET'){$q=$conn->prepare('SELECT id,name,email,role,phone,shipping_address,billing_address,created_at FROM users WHERE id=?');$q->bind_param('i',$uid);$q->execute();$u=$q->get_result()->fetch_assoc();$u['shipping_address']=decryptField($u['shipping_address']);$u['billing_address']=decryptField($u['billing_address']);unset($u['password']);echo json_encode(['success'=>true,'profile'=>$u]);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$d=json_decode(file_get_contents('php://input'),true)??$_POST;$name=trim($d['name']??'');$phone=trim($d['phone']??'');$ship=encryptField(trim($d['shipping_address']??''));$bill=encryptField(trim($d['billing_address']??''));$q=$conn->prepare('UPDATE users SET name=?,phone=?,shipping_address=?,billing_address=? WHERE id=?');$q->bind_param('ssssi',$name,$phone,$ship,$bill,$uid);$ok=$q->execute();echo json_encode(['success'=>$ok]);exit;}http_response_code(405);
